package com.keyforge.nativeiiq.wire;
import com.keyforge.nativeiiq.model.*; import java.time.Instant; import java.util.*;
public final class NativeWorkflowWire { private NativeWorkflowWire(){} public static Map<String,Object> error(int status,Throwable t){Map<String,Object>e=new LinkedHashMap<>();e.put("type",t==null?null:t.getClass().getName());e.put("message",t==null?null:String.valueOf(t.getMessage()));Map<String,Object>m=new LinkedHashMap<>();m.put("entity","Workflow");m.put("status",status);m.put("error",e);return m;} public static Map<String,Object> envelope(NativeWorkflowExtractionResult r,int start,int limit){List<Object>rows=new ArrayList<>();for(NativeWorkflowRow w:r.getWorkflows()){Map<String,Object>m=new LinkedHashMap<>();m.put("sourceId",w.getSourceId());m.put("name",w.getName());m.put("type",w.getType());m.put("handler",w.getHandler());m.put("description",w.getDescription());m.put("taskType",w.getTaskType());m.put("created",iso(w.getCreated()));m.put("modified",iso(w.getModified()));m.put("definition",w.getDefinition());m.put("srcSystem",w.getSrcSystem());m.put("srcInterface","native_iiq_java_api");m.put("srcObjectType","sailpoint.object.Workflow");m.put("extractionRunId",w.getExtractionRunId());m.put("extractedAt",iso(w.getExtractedAt()));rows.add(m);}Map<String,Object>e=new LinkedHashMap<>();e.put("entity","Workflow");e.put("sourceSystem",r.getSourceSystem());e.put("extractionRunId",r.getExtractionRunId());e.put("start",start);e.put("limit",limit);e.put("returned",rows.size());e.put("rows",rows);return e;} private static String iso(Instant i){return i==null?null:i.toString();} }
